// ❌ REACT: Every time 'setTheme' is called, React re-renders the Provider,
// every component in between (unless heavily memoized), and all consumers.
import { createContext, useContext, useState } from 'react';

const ThemeContext = createContext('light');

export function App() {
  const [theme, setTheme] = useState('light');
  return (
    <ThemeContext.Provider value={theme}>
      <MiddleComponent />
      <button onClick={() => setTheme(t => t === 'light' ? 'dark' : 'light')}>Toggle</button>
    </ThemeContext.Provider>
  );
}

function MiddleComponent() {
  console.log('MiddleComponent re-rendered!'); // ❌ Runs on every theme change!
  return <Consumer />;
}

function Consumer() {
  const theme = useContext(ThemeContext);
  return <div className={theme}>Theme: {theme}</div>;
}

// ✅ SOLIDJS: MiddleComponent runs EXACTLY ONCE on mount.
// Changing theme updates ONLY the <div> className text node directly!
import { createContext, useContext, createSignal } from 'solid-js';

const ThemeContext = createContext();

export function App() {
  const [theme, setTheme] = createSignal('light');
  return (
    <ThemeContext.Provider value={theme}>
      <MiddleComponent />
      <button onClick={() => setTheme(t => t === 'light' ? 'dark' : 'light')}>Toggle</button>
    </ThemeContext.Provider>
  );
}

function MiddleComponent() {
  console.log('MiddleComponent initialized!'); // ✅ Logs ONCE on startup, never again!
  return <Consumer />;
}

function Consumer() {
  const theme = useContext(ThemeContext); // theme is the signal accessor [get]
  return <div class={theme()}>Theme: {theme()}</div>;
}
